SET phone = v.phone
FROM (
  VALUES
    ('10000000-0000-0000-0000-000000000001'::uuid, '312-555-1101'),
    ('10000000-0000-0000-0000-000000000002'::uuid, '312-555-1102'),
    ('10000000-0000-0000-0000-000000000003'::uuid, '312-555-1103'),
    ('10000000-0000-0000-0000-000000000004'::uuid, '312-555-1104'),
    ('10000000-0000-0000-0000-000000000005'::uuid, '312-555-1105'),
    ('10000000-0000-0000-0000-000000000006'::uuid, '312-555-1106'),
    ('10000000-0000-0000-0000-000000000007'::uuid, '312-555-1107'),
    ('10000000-0000-0000-0000-000000000008'::uuid, '312-555-1108'),
    ('10000000-0000-0000-0000-000000000009'::uuid, '312-555-1109'),
    ('10000000-0000-0000-0000-000000000010'::uuid, '312-555-1110'),
    ('10000000-0000-0000-0000-000000000011'::uuid, '312-555-1111'),
    ('10000000-0000-0000-0000-000000000012'::uuid, '312-555-1112'),
    ('10000000-0000-0000-0000-000000000013'::uuid, '312-555-1113'),
